const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Washington D.C. location
  const dcPoint = ee.Geometry.Point([-77.0369, 38.9072]);
  const dcBuffer = dcPoint.buffer(10000); // ~10 km buffer for region

  // Define 2018 date range
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // Load PERSIANN-CDR daily rainfall data
  let rainCollection = ee.ImageCollection('NOAA/PERSIANN-CDR')
    .filterDate(startDate, endDate)
    .filterBounds(dcBuffer);

  // Check if collection has data
  const colSize = await rainCollection.size().getInfo();
  console.log(`2018 Daily Rainfall Images: ${colSize}`);

  if (colSize === 0) {
    console.log('No rainfall data found for 2018 in Washington D.C.');
    console.log('C1');
    return;
  }

  // Sum all daily precipitation over the year
  const totalRainfall = rainCollection
    .select('precipitation')
    .sum();

  // Calculate total rainfall in mm
  const stats = await totalRainfall.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: dcPoint,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const totalMm = stats['precipitation'];
  const totalInches = totalMm / 25.4;

  // Validate result
  if (totalMm === null || totalMm === undefined || isNaN(totalMm)) {
    console.log('Rainfall calculation returned null or NaN.');
    console.log('C3');
    return;
  }

  if (totalMm <= 0) {
    console.log('Total rainfall is 0 or negative - likely no valid pixels.');
    console.log('C2');
    return;
  }

  // Output results
  console.log(`2018 Total Rainfall: ${totalInches.toFixed(2)} inches (${totalMm.toFixed(1)} mm)`);
  console.log(`Threshold: 50 inches`);

  // Final answer
  if (totalInches >= 50) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
